def determine_unit_and_convert(value, feature_name, config):
    """Determine if value is in alternative units and convert if needed"""
    if pd.isna(value):
        return np.nan

    if feature_name not in config:
        return value

    feature_config = config[feature_name]
    us_min, us_max = feature_config['range']
    alt_factor = feature_config.get('alt_factor', 1)
    alt_range = feature_config.get('alt_range')

    # Special handling for count-based features first
    if feature_name in ['WBC_Count', 'Platelet_Count']:
        if value > 1000:  # Likely in /µL instead of K/µL
            return value / 1000
        return value

    # Special handling for protein measurements (g/L to g/dL)
    if feature_name in ['Hemoglobin', 'Albumin_Serum', 'Total_Protein']:
        # If significantly above US conventional range, likely in g/L
        if value > us_max * 3:
            return value * 0.1
        # If within normal range, keep as is
        if us_min * 0.5 <= value <= us_max * 1.5:
            return value
        # If in alternative range
        if alt_range:
            alt_min, alt_max = alt_range
            if alt_min * 0.7 <= value <= alt_max * 1.5:
                return value * alt_factor
        return value

    # If value is within US conventional range (with tolerance), keep it
    if us_min * 0.7 <= value <= us_max * 1.5:
        return value

    # If alternative range exists and value is in that range, convert
    if alt_range:
        alt_min, alt_max = alt_range
        # Check if value is clearly in alternative range
        if alt_min * 0.7 <= value <= alt_max * 1.5:
            # Convert from alternative unit to US conventional
            converted = value * alt_factor
            # Verify conversion makes sense (result should be in US range)
            if us_min * 0.5 <= converted <= us_max * 2:
                return converted
            else:
                # Conversion didn't work, keep original
                return value

    # Special case for creatinine (very common conversion)
    if feature_name == 'Serum_Creatinine':
        if value > 20:  # Likely in µmol/L
            return value * 0.0113

    # For very large values that might need conversion
    if alt_factor < 1:
        if value > us_max * 10:
            converted = value * alt_factor
            if us_min * 0.5 <= converted <= us_max * 2:
                return converted

    # For very small values that might need conversion
    if alt_factor > 1:
        if value < us_min / 10:
            converted = value * alt_factor
            if us_min * 0.5 <= converted <= us_max * 2:
                return converted

    # If no conversion applied, return original value
    return value

